public sealed partial class MermaidNotationReferenceRenderingTests {
    [MermaidReferenceTheory] [Trait("Category","MermaidReference")] [InlineData(false)] [InlineData(true)]
    public async Task OmittedSequenceShadowScopesRetainActualDefinitionTargetsWhenOnlyStylesheetShadowChanges(bool disableStyle) {
        var corpus=Path.Combine(TestRepository.Root,"tests","mermaid-conformance");using var manifest=JsonDocument.Parse(File.ReadAllText(Path.Combine(corpus,"compatibility.json")));var reference=manifest.RootElement.GetProperty("references").GetProperty("12");var bundle=Path.Combine(corpus,"node_modules",reference.GetProperty("package").GetString()!);using var installed=JsonDocument.Parse(File.ReadAllText(Path.Combine(bundle,"package.json")));Assert.Equal(reference.GetProperty("version").GetString(),installed.RootElement.GetProperty("version").GetString());var source=(disableStyle?"%%{init:{\"themeVariables\":{\"dropShadow\":\"none\"}}}%%\n":"")+"sequenceDiagram\nparticipant A as Review\nparticipant B as Archive\nA->>B: Save\nloop Audit\nB-->>A: Stored\nend\nNote over A,B: Retain facts";var native=MermaidRenderer.Render(source,new MermaidRenderOptions{Presentation=new MermaidPresentationOptions{FontFamily=BrowserProofFonts.Family}});Assert.False(native.HasErrors);
        var artifact = native.Artifact ?? throw new InvalidOperationException("The source shadow fixture did not produce an artifact.");
        var svg=artifact.ToSvg();var png=artifact.ToPng();await using var session=await BrowserProofFonts.OpenAsync("<style>body{margin:0}section{overflow:auto;max-width:100%}</style><section id='reference'></section><section id='native'>"+svg+"</section>",1100,1000);await session.Page.AddScriptTagAsync(new PageAddScriptTagOptions{Path=Path.Combine(bundle,"dist","mermaid.min.js")});var observed=await session.Page.EvaluateReferenceJsonAsync("""
            async ({source,fontFamily})=>{mermaid.initialize({startOnLoad:false,securityLevel:'strict',deterministicIds:true,fontFamily});const out=await mermaid.render('e01-reference-shadow',source);document.querySelector('#reference').innerHTML=out.svg;await document.fonts.ready;const s=document.querySelector('#reference svg');const defs=[...s.querySelectorAll('filter')].map(f=>({id:f.id,x:f.getAttribute('x'),y:f.getAttribute('y'),width:f.getAttribute('width'),height:f.getAttribute('height'),xml:f.outerHTML}));const selected=e=>{const value=getComputedStyle(e).filter;const target=/#([^)'"\s]+)/.exec(value)?.[1]??null;return {tag:e.tagName,css:e.getAttribute('class'),attribute:e.getAttribute('filter'),computed:value,target,resolves:target?defs.some(f=>f.id===target):null,html:e.outerHTML}};return {defs,participants:[...s.querySelectorAll('g[data-et="participant"] [filter]')].map(selected),styles:[...s.querySelectorAll('rect.note,.labelBox,g rect.rect,rect.actor')].map(selected),svg:s.outerHTML,source};}
            """,new{source,fontFamily=BrowserProofFonts.Family});var output=Environment.GetEnvironmentVariable("CFX_BROWSER_CAPTURE_DIRECTORY");if(!string.IsNullOrWhiteSpace(output)){Directory.CreateDirectory(output);var stem=Path.Combine(output,"surface-shadow-reference-before-"+disableStyle);File.WriteAllText(stem+".mmd",source);File.WriteAllText(stem+".observed.json",observed.GetRawText());File.WriteAllText(stem+".reference.svg",observed.GetProperty("svg").GetString());File.WriteAllText(stem+".native.svg",svg);File.WriteAllBytes(stem+".native.png",png);File.WriteAllText(stem+".native.json",artifact.ToInterchangeJson());await session.Page.ScreenshotAsync(new PageScreenshotOptions{Path=stem+".browser.png",FullPage=true});}Assert.True(observed.GetProperty("participants").GetArrayLength()>=2);Assert.All(observed.GetProperty("participants").EnumerateArray(),p=>Assert.True(p.GetProperty("resolves").GetBoolean()));Assert.Contains(observed.GetProperty("defs").EnumerateArray(),d=>d.GetProperty("id").GetString()=="e01-reference-shadow-drop-shadow");InteractiveChartBrowser.AssertNoConsoleErrors(session);
    }
